@dataclass(slots=True)
class AnatomyOfAConfig:
    """Configuration for the Anatomy of a Prompt component in a Prompt Engineering system."""

    name: str
    timeout_s: float = 30.0
    max_retries: int = 3
    options: dict[str, Any] = field(default_factory=dict)


class AnatomyOfA:
